export const leaveBehindId = (number: StoryLessonNumber) => `conversational-skills-L6-C5-${number}-${leaveBehindEpisodes[number].skill}-en-v1`;

export function buildLeaveBehindLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, leaveBehindEpisodes[number], previous, reference, {
    id: leaveBehindId(number), chapterName: 'What We Leave Behind', pronunciation: naturalPronunciationLessons[5][number],
    setting: 'Kanazawa: Haru’s fictional family Kaga Yuzen workshop, its historical exhibition and the beginning of a shared teaching programme. The supplied rural-festival return is the opening context; no additional intervening events are established.',
    previousSummary: index === 0 ? 'The friends have helped a rural community preserve its festival. Haru returns to Kanazawa and the family workshop.' : leaveBehindEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(6)}\nReference: What We Leave Behind, the final chapter of Threads of Tradition. Eight episodes map to slots 1-4 and 6-9; 5/10 remain dynamic checkpoints. English only, four contextual Step A expressions, tutor-first short dialogue, private listening, fresh visible reading evidence and fixed English feedback. Pronunciation exists only in Step B, with relevant linking/grouping guides and exact bold stress. No Part III, unnecessary pronunciation commentary, new images or romance. Use only the rural-festival return supplied in this reference as opening context; do not invent an intervening chapter. Retirement is from full-time work at year’s end; the autumn demonstration is the final one in that full-time role, not a promise never to demonstrate again. Mrs. Takeda remains an occasional mentor. Haru’s choice is voluntary and develops in stages. The photograph shows her at nineteen; no calendar year is supplied. Historical recording permission is not blanket future-use permission. Begin small with quality as the expansion condition. The six-month trial is agreed in episode five/slot six; it is beginning, not completed, at the ending. Budget categories have no invented amounts, profits or fees. School contacts become scheduled visits only in the final episode. Haru coordinates and learns; experienced local artisans support teaching. Broaden the exhibition to former apprentices, colleagues and craftspeople without inventing identities or honours. Beginner interest at the exhibition is not an enrolment. End with the first student arriving, patient orientation, all friends’ concluding projects, Mrs. Takeda’s welcome and Daniel lowering the camera to be present. This is the conclusion; do not add a sequel.`,
  });
  lesson.storyData.storyTitle = 'Threads of Tradition';
  lesson.storyData.characters = [
    { id: 'haru', name: 'Haru', role: 'main', description: 'Kanazawa workshop family member. He chooses shared daily coordination, keeps developing his skills and welcomes the first learners.' },
    { id: 'takeda', name: 'Mrs. Takeda', role: 'supporting', description: 'Experienced Kaga Yuzen artisan. She retires from full-time work at year’s end and remains an occasional mentor, valuing both standards and community.' },
    { id: 'aiko', name: 'Aiko', role: 'supporting', description: 'Museum educator based in Tokyo. She helps with history, school contacts and mediation, then develops a cultural education programme.' },
    { id: 'mei', name: 'Mei', role: 'supporting', description: 'Chef from Kyoto. She supports a craft-and-food programme and exhibition refreshments, then creates regional food stories with participating families’ agreement.' },
    { id: 'daniel', name: 'Daniel', role: 'supporting', description: 'Canadian photographer living in Japan. He records history with permission, completes a documentary series and finally chooses to experience the welcome without his camera.' },
  ];
  if (number === 9) lesson.missionData.tutorSteps[1].scripts[0].text = "I'll be a new student. Please be Haru. You may use the useful language. I'll start.";
  return { ...lesson, course: 'conversational-skills', level: 6, chapter: 5, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 5: What We Leave Behind', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildLeaveBehindChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildLeaveBehindLesson(number, {}, reference));
}
